-- Loads every engine rules area file (see README.md) and returns one list.
-- From the repo root: local rules = dofile("Tools/engine/rules.lua")
-- wiki-tags is generated by Tools/engine/wikiapi.py (inferred rules from the Warcraft Wiki's API tags).
local AREAS = { "secrets-combat", "nameplates-units", "camera-movement", "ui-frames", "wiki-tags" }

local all = {}
for _, area in ipairs(AREAS) do
    local path = "Tools/engine/rules/" .. area .. ".lua"
    local list = assert(loadfile(path))()
    for _, r in ipairs(list) do
        r.file = area
        all[#all + 1] = r
    end
end
return all, AREAS
